export async function logPageView(data: {
  page: string;
  timestamp: string;
  userAgent?: string;
}) {
  console.log('[Analytics] Page view logged:', data);

  // Simulate an API call to an analytics service
  // In production, this would call your actual analytics service
  // e.g., await fetch('https://analytics.example.com/log', { ... })

  await new Promise(resolve => setTimeout(resolve, 100));
}

